"""Privacy and trust answers (what this app actually does with your information, what it cannot do, how sources are handled)
and a finder for official places to verify facts (reliable answers). Pure Python, four languages.
These texts describe THIS app's behaviour; update them if the app's behaviour changes (for example if chat history is ever stored).
fr/rw/sw wording is a draft for fluent review. Source addresses come from general knowledge and could not be opened from the build environment: check them."""
from __future__ import annotations
from textutil import fold, has_phrase, lk, entry, LANGS


def _e(id_, title, answer, steps=None, steps_label=None, related=None):
    st = {l: list(steps[i]) if steps else [] for i, l in enumerate(LANGS)}
    return entry(id_, "trust", dict(zip(LANGS, title)), dict(zip(LANGS, answer)), st, dict(zip(LANGS, steps_label)) if steps_label else None, related)


