def sources_entry(topic=None):
    keys = [topic] if topic in _TOPIC else list(_TOPIC)
    ttl = {"en": "Where to verify facts", "fr": "Où vérifier les faits", "rw": "Aho wagenzurira ukuri", "sw": "Mahali pa kuhakiki ukweli"}
    ans = {}
    for l in LANGS:
        lines = []
        for k in keys:
            name, _, srcs = _TOPIC[k]
            lines.append(f"**{name[l]}**")
            lines += [f"- [{n}]({u})" for n, u in srcs]
            lines.append("")
        ans[l] = "\n".join(lines).strip() + "\n\n_" + _UNVERIFIED[l] + "_"
    return entry("trust_where", "trust", ttl, ans, {l: list(_CHECK[l]) for l in LANGS}, dict(_CHECK_T))


