def find(question, lang="en"):
    q = fold(question)
    if not q or len(q) > 140:
        return None
    if has_phrase(q, _WHERE.split("|")):
        topic = None
        for key, (_, kw, _) in _TOPIC.items():
            if has_phrase(q, kw.split("|")):
                topic = key
                break
        return sources_entry(topic)
    for ent, kw in _MATCH:
        if has_phrase(q, kw.split("|")):
            return ent
    return None
